<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Keranjang — Rembang UMKM</title><link rel="icon" href="<?= base_url('assets/favicon.ico?v=1') ?>"><link rel="stylesheet" href="<?= base_url('assets/tabler.min.css') ?>"><link rel="stylesheet" href="<?= base_url('assets/marketplace.css?v=5') ?>"></head><body class="shop-body"><?php $this->load->view('market/_header'); ?><main class="shop-main container-xl"><div class="shop-page-title"><span class="shop-eyebrow">PILIHANMU</span><h1>Keranjang belanja</h1><p>Produk dikelompokkan per toko. Lanjutkan percakapan dengan masing-masing penjual.</p></div><?php if (!$groups): ?><div class="shop-empty"><strong>Keranjang masih kosong</strong><p>Temukan produk menarik dari usaha lokal Rembang.</p><a href="<?= site_url('jelajah') ?>">Jelajahi produk</a></div><?php else: ?><div class="shop-cart-layout"><div><?php foreach ($groups as $group): ?><section class="shop-cart-group"><div class="shop-cart-store"><a href="<?= site_url('toko/'.$group['store_slug']) ?>">◈ <?= html_escape($group['store_name']) ?></a><span><?= count($group['items']) ?> produk</span></div><?php foreach ($group['items'] as $item): ?><div class="shop-cart-item"><a class="shop-cart-item-image" href="<?= site_url('produk/'.$item['product_id']) ?>"><img src="<?= ($item['cover_path'] ? base_url('assets/products/'.rawurlencode($item['cover_path'])) : category_art_url($item['category_slug'] ?: 'ritel')) ?>" alt=""></a><div><a class="shop-cart-item-name" href="<?= site_url('produk/'.$item['product_id']) ?>"><?= html_escape($item['product_name']) ?></a><?php if($item['variant_label']): ?><small class="shop-cart-variant"><?= html_escape($item['variant_label']) ?></small><?php elseif($item['variant_count']): ?><a class="shop-cart-variant" href="<?= site_url('produk/'.$item['product_id']) ?>">Pilih varian untuk melanjutkan</a><?php endif; ?><strong><?= $item['price_min'] !== NULL ? 'Rp'.number_format((float)$item['price_min'],0,',','.') : 'Tanya harga' ?></strong><form class="shop-qty-form" method="post" action="<?= site_url('keranjang/ubah') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="line_id" value="<?= (int)$item['line_id'] ?>"><label>Jumlah <input type="number" name="quantity" value="<?= (int)$item['quantity'] ?>" min="0" max="99" inputmode="numeric"></label><button type="submit">Simpan</button><span>0 untuk hapus</span></form></div></div><?php endforeach; ?><div class="shop-cart-total"><span>Perkiraan subtotal</span><strong>Rp<?= number_format($group['subtotal'],0,',','.') ?></strong></div><form method="post" action="<?= site_url('kontak/keranjang/'.$group['store_id']) ?>" class="shop-cart-checkout"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><button class="shop-primary-button" type="submit">Siapkan pesan untuk toko <span aria-hidden="true">→</span></button></form></section><?php endforeach; ?></div><aside class="shop-cart-aside"><strong>Belanja dari beberapa toko?</strong><p>Setiap toko akan menerima pesan terpisah berisi rincian produknya. Pembayaran dan pengiriman disepakati langsung dengan penjual.</p></aside></div><?php endif; ?></main><?php $active_tab='cart';$this->load->view('market/_bottom_nav', array('active_tab' => $active_tab, 'cart_count' => $cart_count)); ?></body></html>
